import{_ as o}from"./chunks/第一步-03.D7lAR9Hu.js";import{_ as t}from"./chunks/工作台-1700.k7zo2HQv.js";import{_ as a,o as r,c as d,a2 as s}from"./chunks/framework.CqGPl1zp.js";const l="/newx-doc/assets/%E7%AC%AC%E4%B8%80%E6%AD%A5-01.CFeAvj7l.png",p="/newx-doc/assets/%E7%AC%AC%E4%B8%80%E6%AD%A5-02.a6Fs8uxW.png",i="/newx-doc/assets/%E7%AC%AC%E4%BA%8C%E6%AD%A5-01.CacQxH6j.png",x=JSON.parse('{"title":"功能开启","description":"","frontmatter":{},"headers":[],"relativePath":"pms/build.md","filePath":"pms/build.md","lastUpdated":null}'),c={name:"pms/build.md"};function m(n,e,u,_,h,b){return r(),d("div",null,[...e[0]||(e[0]=[s('<h1 id="功能开启" tabindex="-1">功能开启 <a class="header-anchor" href="#功能开启" aria-label="Permalink to &quot;功能开启&quot;">​</a></h1><p>进度说明：</p><ul><li>管理后台，请使用 <a href="https://gitee.com/yudaocode/yudao-ui-admin-vue3" target="_blank" rel="noreferrer">https://gitee.com/yudaocode/yudao-ui-admin-vue3</a> 仓库的 <code>master</code> 分支</li><li>后端项目，请使用 <a href="https://gitee.com/zhijiantianya/ruoyi-vue-pro" target="_blank" rel="noreferrer">https://gitee.com/zhijiantianya/ruoyi-vue-pro</a> 仓库的 <code>master</code>（JDK8）、<code>master-jdk17</code>（JDK17/21）或 <code>master-jdk25</code>（JDK25）分支</li></ul><p>PMS 系统，后端由 <code>yudao-module-pms</code> 模块实现，前端由 <code>yudao-ui-admin-vue3</code> 的 <code>pms</code> 目录实现。</p><p>考虑到编译速度，默认 <code>yudao-module-pms</code> 模块是关闭的，需要手动开启。步骤如下：</p><ul><li>第一步，开启 <code>yudao-module-pms</code> 模块</li><li>第二步，导入 PMS 系统的 SQL 数据库脚本</li><li>第三步，重启后端项目，确认功能是否生效</li></ul><h2 id="_1-第一步-开启模块" tabindex="-1">1. 第一步，开启模块 <a class="header-anchor" href="#_1-第一步-开启模块" aria-label="Permalink to &quot;1. 第一步，开启模块&quot;">​</a></h2><p>① 修改根目录的 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/pom.xml" target="_blank" rel="noreferrer"><code>pom.xml</code></a> 文件，取消 <code>yudao-module-pms</code> 模块的注释。如下图所示：</p><p><img src="'+l+'" alt="取消  模块的注释"></p><p>② 修改 <code>yudao-server</code> 目录的 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-server/pom.xml" target="_blank" rel="noreferrer"><code>pom.xml</code></a> 文件，引入 <code>yudao-module-pms</code> 模块。如下图所示：</p><p><img src="'+p+'" alt="引入  模块"></p><p>③ 点击 IDEA 右上角的【Reload All Maven Projects】，刷新 Maven 依赖。如下图所示：</p><p><img src="'+o+'" alt="刷新 Maven 依赖"></p><h2 id="_2-第二步-导入-sql" tabindex="-1">2. 第二步，导入 SQL <a class="header-anchor" href="#_2-第二步-导入-sql" aria-label="Permalink to &quot;2. 第二步，导入 SQL&quot;">​</a></h2><p>点击 <a href="https://lwb8832652.github.io/newx-doc/sql/pms.sql" target="_blank" rel="noreferrer">下载 SQL</a> 直接下载 SQL 文件，导入到数据库中。如下图所示：</p><p>友情提示：↑↑↑ pms.sql 是可以点击下载的！ ↑↑↑</p><p>重要说明：该 SQL 仅芋道星球成员可使用和商用，否则视为侵权（索赔 100 万，永久追溯）【下载即视为同意】。</p><p><img src="'+i+'" alt="导入数据库"></p><p>以 <code>pms_</code> 作为前缀的表，就是 PMS 模块当前源码维护的表，一共 <strong>33</strong> 张，按业务模块分为：</p><table tabindex="0"><thead><tr><th>子前缀</th><th>模块</th><th>表数量</th></tr></thead><tbody><tr><td><code>pms_project*</code>、<code>pms_iteration</code>、<code>pms_work_item*</code></td><td>项目中心</td><td>17</td></tr><tr><td><code>pms_knowledge_*</code></td><td>知识中心</td><td>16</td></tr></tbody></table><h2 id="_3-第三步-重启项目" tabindex="-1">3. 第三步，重启项目 <a class="header-anchor" href="#_3-第三步-重启项目" aria-label="Permalink to &quot;3. 第三步，重启项目&quot;">​</a></h2><p>重启后端项目，然后访问前端的 PMS 菜单，确认功能是否生效。如下图所示：</p><p><img src="'+t+'" alt="确认功能是否生效"></p><p>进入 [PMS 项目管理 -&gt; 项目中心 -&gt; 工作台]，确认工作项和迭代的数量统计、列表可以正常返回；再进入「我的项目」和「知识中心 -&gt; 知识库」，确认项目列表和知识库列表可以正常加载。</p><p>至此，我们就成功开启了 PMS 的功能 🙂</p><h2 id="_4-全局说明" tabindex="-1">4. 全局说明 <a class="header-anchor" href="#_4-全局说明" aria-label="Permalink to &quot;4. 全局说明&quot;">​</a></h2><p>① <strong>回收站清理依赖定时任务</strong>：知识库回收站默认保留 30 天，由 PmsKnowledgeRecycleCleanJob 清理到期记录。请在 [基础设施 -&gt; 定时任务] 中配置该 Job（如果是微服务版本，需要去 XXL-Job 里配置）。未配置时，到期记录会一直保留在回收站中。</p>',27)])])}const A=a(c,[["render",m]]);export{x as __pageData,A as default};
